     1→import {toHexString} from "@chainsafe/ssz";
     2→import {ChainForkConfig} from "@lodestar/config";
     3→import {ForkName, NUMBER_OF_COLUMNS, isForkPostDeneb} from "@lodestar/params";
     4→import {RootHex, SignedBeaconBlock, deneb, fulu, ssz} from "@lodestar/types";
     5→import {Logger, pruneSetToMax} from "@lodestar/utils";
     6→
     7→import {IExecutionEngine} from "../../execution/index.js";
     8→import {Metrics} from "../../metrics/index.js";
     9→import {IClock} from "../../util/clock.js";
    10→import {
    11→  CustodyConfig,
    12→  RecoverResult,
    13→  getDataColumnsFromExecution,
    14→  hasSampledDataColumns,
    15→  recoverDataColumnSidecars,
    16→} from "../../util/dataColumns.js";
    17→import {callInNextEventLoop} from "../../util/eventLoop.js";
    18→import {
    19→  BlobsSource,
    20→  BlockInput,
    21→  BlockInputBlobs,
    22→  BlockInputDataColumns,
    23→  BlockSource,
    24→  CachedData,
    25→  CachedDataColumns,
    26→  DataColumnsSource,
    27→  GossipedInputType,
    28→  NullBlockInput,
    29→  getBlockInput,
    30→  getBlockInputBlobs,
    31→  getBlockInputDataColumns,
    32→} from "../blocks/types.js";
    33→import {ChainEvent, ChainEventEmitter} from "../emitter.js";
    34→import {DataColumnSidecarErrorCode, DataColumnSidecarGossipError} from "../errors/dataColumnSidecarError.js";
    35→import {GossipAction} from "../errors/gossipValidation.js";
    36→
    37→export enum BlockInputAvailabilitySource {
    38→  GOSSIP = "gossip",
    39→  RECOVERED = "recovered",
    40→  UNKNOWN_SYNC = "unknown_sync",
    41→}
    42→
    43→type GossipedBlockInput =
    44→  | {type: GossipedInputType.block; signedBlock: SignedBeaconBlock}
    45→  | {type: GossipedInputType.blob; blobSidecar: deneb.BlobSidecar}
    46→  | {
    47→      type: GossipedInputType.dataColumn;
    48→      dataColumnSidecar: fulu.DataColumnSidecar;
    49→      dataColumnBytes: Uint8Array | null;
    50→    };
    51→
    52→// TODO(fulu): dedup with gossipHandlers.ts
    53→const BLOCK_AVAILABILITY_CUTOFF_MS = 3_000;
    54→
    55→export type BlockInputCacheType = {
    56→  fork: ForkName;
    57→  block?: SignedBeaconBlock;
    58→  cachedData?: CachedData;
    59→  // block promise and its callback cached for delayed resolution
    60→  blockInputPromise: Promise<BlockInput>;
    61→  resolveBlockInput: (blockInput: BlockInput) => void;
    62→};
    63→
    64→type GossipBlockInputResponseWithBlock = {
    65→  blockInput: BlockInput;
    66→  blockInputMeta:
    67→    | {pending: GossipedInputType.blob | null; haveBlobs: number; expectedBlobs: number}
    68→    | {pending: GossipedInputType.dataColumn | null; haveColumns: number; expectedColumns: number};
    69→};
    70→
    71→type BlockInputPendingBlock = {pending: GossipedInputType.block};
    72→export type BlockInputMetaPendingBlockWithBlobs = BlockInputPendingBlock & {haveBlobs: number; expectedBlobs: null};
    73→type BlockInputMetaPendingBlockWithColumns = BlockInputPendingBlock & {haveColumns: number; expectedColumns: null};
    74→
    75→type GossipBlockInputResponseWithNullBlock = {
    76→  blockInput: NullBlockInput;
    77→  blockInputMeta: BlockInputMetaPendingBlockWithBlobs | BlockInputMetaPendingBlockWithColumns;
    78→};
    79→
    80→type GossipBlockInputResponse = GossipBlockInputResponseWithBlock | GossipBlockInputResponseWithNullBlock;
    81→
    82→const MAX_GOSSIPINPUT_CACHE = 5;
    83→
    84→/**
    85→ * For predeneb, SeenGossipBlockInput only tracks and caches block so that we don't need to download known block
    86→ * roots. From deneb, it serves same purpose plus tracks and caches the live blobs and blocks on the network to
    87→ * solve data availability for the blockInput. If no block has been seen yet for some already seen blobs, it
    88→ * responds will null, but on the first block or the consequent blobs it responds with blobs promise till all blobs
    89→ * become available.
    90→ *
    91→ * One can start processing block on blobs promise blockInput response and can await on the promise before
    92→ * fully importing the block. The blobs promise is gets resolved as soon as all blobs corresponding to that
    93→ * block are seen by SeenGossipBlockInput
    94→ */
    95→export class SeenGossipBlockInput {
    96→  private readonly blockInputCache = new Map<RootHex, BlockInputCacheType>();
    97→  private readonly custodyConfig: CustodyConfig;
    98→  private readonly executionEngine: IExecutionEngine;
    99→  private readonly clock: IClock;
   100→  private readonly emitter: ChainEventEmitter;
   101→  private readonly logger: Logger;
   102→
   103→  constructor(
   104→    custodyConfig: CustodyConfig,
   105→    executionEngine: IExecutionEngine,
   106→    emitter: ChainEventEmitter,
   107→    clock: IClock,
   108→    logger: Logger
   109→  ) {
   110→    this.custodyConfig = custodyConfig;
   111→    this.executionEngine = executionEngine;
   112→    this.clock = clock;
   113→    this.emitter = emitter;
   114→    this.logger = logger;
   115→  }
   116→  globalCacheId = 0;
   117→
   118→  prune(): void {
   119→    pruneSetToMax(this.blockInputCache, MAX_GOSSIPINPUT_CACHE);
   120→  }
   121→
   122→  hasBlock(blockRoot: RootHex): boolean {
   123→    return this.blockInputCache.has(blockRoot);
   124→  }
   125→
   126→  /**
   127→   * Intended to be used for gossip validation, specifically this check:
   128→   * [IGNORE] The sidecar is the first sidecar for the tuple (block_header.slot, block_header.proposer_index,
   129→   *          sidecar.index) with valid header signature, sidecar inclusion proof, and kzg proof
   130→   */
   131→  hasDataColumnSidecar(sidecar: fulu.DataColumnSidecar) {
   132→    const blockRoot = ssz.phase0.BeaconBlockHeader.hashTreeRoot(sidecar.signedBlockHeader.message);
   133→    const blockRootHex = toHexString(blockRoot);
   134→
   135→    const blockCache = this.blockInputCache.get(blockRootHex);
   136→    if (blockCache === undefined) {
   137→      return false;
   138→    }
   139→    if (blockCache.cachedData === undefined || blockCache.cachedData.fork !== ForkName.fulu) {
   140→      return false;
   141→    }
   142→    const existingSidecar = blockCache.cachedData.dataColumnsCache.get(sidecar.index);
   143→    if (!existingSidecar) {
   144→      return false;
   145→    }
   146→    return (
   147→      sidecar.signedBlockHeader.message.slot === existingSidecar.dataColumn.signedBlockHeader.message.slot &&
   148→      sidecar.index === existingSidecar.dataColumn.index &&
   149→      sidecar.signedBlockHeader.message.proposerIndex ===
   150→        existingSidecar.dataColumn.signedBlockHeader.message.proposerIndex
   151→    );
   152→  }
   153→
   154→  getGossipBlockInput(
   155→    config: ChainForkConfig,
   156→    gossipedInput: GossipedBlockInput,
   157→    metrics: Metrics | null
   158→  ): GossipBlockInputResponse {
   159→    let blockHex: RootHex;
   160→    let blockCache: BlockInputCacheType;
   161→    let fork: ForkName;
   162→
   163→    if (gossipedInput.type === GossipedInputType.block) {
   164→      const {signedBlock} = gossipedInput;
   165→      fork = config.getForkName(signedBlock.message.slot);
   166→
   167→      blockHex = toHexString(
   168→        config.getForkTypes(signedBlock.message.slot).BeaconBlock.hashTreeRoot(signedBlock.message)
   169→      );
   170→      blockCache = this.blockInputCache.get(blockHex) ?? getEmptyBlockInputCacheEntry(fork, ++this.globalCacheId);
   171→
   172→      blockCache.block = signedBlock;
   173→    } else if (gossipedInput.type === GossipedInputType.blob) {
   174→      const {blobSidecar} = gossipedInput;
   175→      const blockRoot = ssz.phase0.BeaconBlockHeader.hashTreeRoot(blobSidecar.signedBlockHeader.message);
   176→      fork = config.getForkName(blobSidecar.signedBlockHeader.message.slot);
   177→
   178→      blockHex = toHexString(blockRoot);
   179→      blockCache = this.blockInputCache.get(blockHex) ?? getEmptyBlockInputCacheEntry(fork, ++this.globalCacheId);
   180→      if (blockCache.cachedData?.fork !== ForkName.deneb && blockCache.cachedData?.fork !== ForkName.electra) {
   181→        throw Error(`blob data at non deneb/electra fork=${blockCache.fork}`);
   182→      }
   183→
   184→      // TODO: freetheblobs check if its the same blob or a duplicate and throw/take actions
   185→      blockCache.cachedData?.blobsCache.set(blobSidecar.index, blobSidecar);
   186→    } else if (gossipedInput.type === GossipedInputType.dataColumn) {
   187→      const {dataColumnSidecar, dataColumnBytes} = gossipedInput;
   188→      const blockRoot = ssz.phase0.BeaconBlockHeader.hashTreeRoot(dataColumnSidecar.signedBlockHeader.message);
   189→      fork = config.getForkName(dataColumnSidecar.signedBlockHeader.message.slot);
   190→
   191→      blockHex = toHexString(blockRoot);
   192→      blockCache = this.blockInputCache.get(blockHex) ?? getEmptyBlockInputCacheEntry(fork, ++this.globalCacheId);
   193→      if (blockCache.cachedData?.fork !== ForkName.fulu) {
   194→        throw Error(`data column data at non fulu fork=${blockCache.fork}`);
   195→      }
   196→
   197→      if (this.hasDataColumnSidecar(dataColumnSidecar)) {
   198→        throw new DataColumnSidecarGossipError(GossipAction.IGNORE, {
   199→          code: DataColumnSidecarErrorCode.ALREADY_KNOWN,
   200→          slot: dataColumnSidecar.signedBlockHeader.message.slot,
   201→          columnIdx: dataColumnSidecar.index,
   202→        });
   203→      }
   204→
   205→      blockCache.cachedData?.dataColumnsCache.set(dataColumnSidecar.index, {
   206→        dataColumn: dataColumnSidecar,
   207→        // easily splice out the unsigned message as blob is a fixed length type
   208→        dataColumnBytes: dataColumnBytes?.slice(0, dataColumnBytes.length) ?? null,
   209→      });
   210→    } else {
   211→      // somehow helps resolve typescript that all types have been exausted
   212→      throw Error("Invalid gossipedInput type");
   213→    }
   214→
   215→    if (!this.blockInputCache.has(blockHex)) {
   216→      this.blockInputCache.set(blockHex, blockCache);
   217→      callInNextEventLoop(() => {
   218→        getDataColumnsFromExecution(config, this.custodyConfig, this.executionEngine, this.emitter, blockCache, metrics)
   219→          .then((_success) => {
   220→            // TODO: (@matthewkeil) add metrics collection point here
   221→          })
   222→          .catch((error) => {
   223→            this.logger.warn("Error getting data columns from execution", {blockHex}, error);
   224→          });
   225→      });
   226→    }
   227→
   228→    const {block: signedBlock, blockInputPromise, resolveBlockInput, cachedData} = blockCache;
   229→
   230→    if (signedBlock !== undefined) {
   231→      if (!isForkPostDeneb(fork)) {
   232→        return {
   233→          blockInput: getBlockInput.preData(config, signedBlock, BlockSource.gossip),
   234→          blockInputMeta: {pending: null, haveBlobs: 0, expectedBlobs: 0},
   235→        };
   236→      }
   237→
   238→      if (cachedData === undefined || !isForkPostDeneb(cachedData.fork)) {
   239→        throw Error("Missing or Invalid fork cached Data for post-deneb block");
   240→      }
   241→
   242→      if (cachedData.fork === ForkName.deneb || cachedData.fork === ForkName.electra) {
   243→        const {blobsCache, resolveAvailability} = cachedData;
   244→
   245→        // block is available, check if all blobs have shown up
   246→        const {slot, body} = signedBlock.message;
   247→        const {blobKzgCommitments} = body as deneb.BeaconBlockBody;
   248→        const blockInfo = `blockHex=${blockHex}, slot=${slot}`;
   249→
   250→        if (blobKzgCommitments.length < blobsCache.size) {
   251→          throw Error(
   252→            `Received more blobs=${blobsCache.size} than commitments=${blobKzgCommitments.length} for ${blockInfo}`
   253→          );
   254→        }
   255→
   256→        if (blobKzgCommitments.length === blobsCache.size) {
   257→          const allBlobs = getBlockInputBlobs(blobsCache);
   258→          const {blobs} = allBlobs;
   259→          const blockData = {
   260→            fork: cachedData.fork,
   261→            ...allBlobs,
   262→            blobsSource: BlobsSource.gossip,
   263→          };
   264→          resolveAvailability(blockData);
   265→          metrics?.syncUnknownBlock.resolveAvailabilitySource.inc({source: BlockInputAvailabilitySource.GOSSIP});
   266→
   267→          const blockInput = getBlockInput.availableData(config, signedBlock, BlockSource.gossip, blockData);
   268→
   269→          resolveBlockInput(blockInput);
   270→          return {
   271→            blockInput,
   272→            blockInputMeta: {pending: null, haveBlobs: blobs.length, expectedBlobs: blobKzgCommitments.length},
   273→          };
   274→        }
   275→
   276→        const blockInput = getBlockInput.dataPromise(config, signedBlock, BlockSource.gossip, cachedData);
   277→
   278→        resolveBlockInput(blockInput);
   279→        return {
   280→          blockInput,
   281→          blockInputMeta: {
   282→            pending: GossipedInputType.blob,
   283→            haveBlobs: blobsCache.size,
   284→            expectedBlobs: blobKzgCommitments.length,
   285→          },
   286→        };
   287→      }
   288→
   289→      if (cachedData.fork === ForkName.fulu) {
   290→        const {dataColumnsCache, resolveAvailability, calledRecover} = cachedData as CachedDataColumns;
   291→
   292→        // block is available, check if all blobs have shown up
   293→        const {slot} = signedBlock.message;
   294→        const blockInfo = `blockHex=${blockHex}, slot=${slot}`;
   295→
   296→        if (NUMBER_OF_COLUMNS < dataColumnsCache.size) {
   297→          throw Error(
   298→            `Received more dataColumns=${dataColumnsCache.size} than columns=${NUMBER_OF_COLUMNS} for ${blockInfo}`
   299→          );
   300→        }
   301→
   302→        // get the custody columns and see if we have got all the requisite columns
   303→        const blobKzgCommitmentsLen = (signedBlock.message.body as deneb.BeaconBlockBody).blobKzgCommitments.length;
   304→        if (blobKzgCommitmentsLen === 0) {
   305→          const blockData: BlockInputDataColumns = {
   306→            fork: cachedData.fork,
   307→            dataColumns: [],
   308→            dataColumnsBytes: [],
   309→            dataColumnsSource: DataColumnsSource.gossip,
   310→          };
   311→          resolveAvailability(blockData);
   312→          metrics?.syncUnknownBlock.resolveAvailabilitySource.inc({source: BlockInputAvailabilitySource.GOSSIP});
   313→
   314→          const blockInput = getBlockInput.availableData(config, signedBlock, BlockSource.gossip, blockData);
   315→
   316→          resolveBlockInput(blockInput);
   317→          return {
   318→            blockInput,
   319→            blockInputMeta: {pending: null, haveColumns: 0, expectedColumns: 0},
   320→          };
   321→        }
   322→
   323→        const resolveAvailabilityAndBlockInput = (source: BlockInputAvailabilitySource) => {
   324→          const allDataColumns = getBlockInputDataColumns(dataColumnsCache, this.custodyConfig.sampledColumns);
   325→          const blockData: BlockInputDataColumns = {
   326→            fork: cachedData.fork,
   327→            ...allDataColumns,
   328→            dataColumnsSource: DataColumnsSource.gossip,
   329→          };
   330→          resolveAvailability(blockData);
   331→          // TODO(das): should not use syncUnknownBlock metrics here
   332→          metrics?.syncUnknownBlock.resolveAvailabilitySource.inc({source});
   333→          metrics?.dataColumns.bySource.inc({source: DataColumnsSource.gossip});
   334→
   335→          const blockInput = getBlockInput.availableData(config, signedBlock, BlockSource.gossip, blockData);
   336→          resolveBlockInput(blockInput);
   337→          return blockInput;
   338→        };
   339→
   340→        const columnCount = dataColumnsCache.size;
   341→        if (
   342→          // only try to recover all columns with "--supernode"
   343→          this.custodyConfig.sampledColumns.length === NUMBER_OF_COLUMNS &&
   344→          columnCount >= NUMBER_OF_COLUMNS / 2 &&
   345→          columnCount < NUMBER_OF_COLUMNS &&
   346→          !calledRecover &&
   347→          // doing recover right away is not efficient because it may delay data_column_sidecar validation
   348→          this.clock.secFromSlot(slot) * 1000 >= BLOCK_AVAILABILITY_CUTOFF_MS
   349→        ) {
   350→          // should call once per slot
   351→          cachedData.calledRecover = true;
   352→          callInNextEventLoop(async () => {
   353→            const logCtx = {
   354→              blockHex,
   355→              slot,
   356→              dataColumns: dataColumnsCache.size,
   357→            };
   358→            const recoverResult = await recoverDataColumnSidecars(dataColumnsCache, this.clock, metrics).catch((e) => {
   359→              this.logger.error("Error recovering data column sidecars", logCtx, e);
   360→              return RecoverResult.Failed;
   361→            });
   362→            metrics?.recoverDataColumnSidecars.reconstructionResult.inc({result: recoverResult});
   363→            switch (recoverResult) {
   364→              case RecoverResult.SuccessResolved: {
   365→                resolveAvailabilityAndBlockInput(BlockInputAvailabilitySource.RECOVERED);
   366→                // Publish columns if and only if subscribed to them
   367→                const sampledColumns = this.custodyConfig.sampledColumns.map((columnIndex) => {
   368→                  const dataColumn = dataColumnsCache.get(columnIndex)?.dataColumn;
   369→                  if (!dataColumn) {
   370→                    throw Error(`After recover, missing data column for index=${columnIndex} in cache`);
   371→                  }
   372→                  return dataColumn;
   373→                });
   374→
   375→                // for columns that we already seen, it will be ignored through `ignoreDuplicatePublishError` gossip option
   376→                this.emitter.emit(ChainEvent.publishDataColumns, sampledColumns);
   377→                this.logger.verbose("Recovered data column sidecars and resolved availability", logCtx);
   378→                break;
   379→              }
   380→              case RecoverResult.SuccessLate:
   381→                this.logger.verbose("Recovered data column sidecars but it's late to resolve availability", logCtx);
   382→                break;
   383→              case RecoverResult.Failed:
   384→                this.logger.verbose("Failed to recover data column sidecars", logCtx);
   385→                break;
   386→              case RecoverResult.NotAttemptedFull:
   387→                this.logger.verbose("Did not attempt because we have full column sidecars", logCtx);
   388→                break;
   389→              case RecoverResult.NotAttemptedLessThanHalf:
   390→                this.logger.verbose("Did not attempt because we have too few column sidecars", logCtx);
   391→                break;
   392→              default:
   393→                break;
   394→            }
   395→          });
   396→        }
   397→        if (hasSampledDataColumns(this.custodyConfig, dataColumnsCache)) {
   398→          const blockInput = resolveAvailabilityAndBlockInput(BlockInputAvailabilitySource.GOSSIP);
   399→          const allDataColumns = getBlockInputDataColumns(dataColumnsCache, this.custodyConfig.sampledColumns);
   400→          const {dataColumns} = allDataColumns;
   401→          return {
   402→            blockInput,
   403→            blockInputMeta: {
   404→              pending: null,
   405→              haveColumns: dataColumns.length,
   406→              expectedColumns: this.custodyConfig.sampledColumns.length,
   407→            },
   408→          };
   409→        }
   410→
   411→        const blockInput = getBlockInput.dataPromise(config, signedBlock, BlockSource.gossip, cachedData);
   412→
   413→        resolveBlockInput(blockInput);
   414→        return {
   415→          blockInput,
   416→          blockInputMeta: {
   417→            pending: GossipedInputType.dataColumn,
   418→            haveColumns: dataColumnsCache.size,
   419→            expectedColumns: this.custodyConfig.sampledColumns.length,
   420→          },
   421→        };
   422→      }
   423→
   424→      throw Error(`Invalid fork=${fork}`);
   425→    }
   426→
   427→    // will need to wait for the block to showup
   428→    if (cachedData === undefined) {
   429→      throw Error("Missing cachedData for deneb+ blobs");
   430→    }
   431→
   432→    if (cachedData.fork === ForkName.deneb || cachedData.fork === ForkName.electra) {
   433→      const {blobsCache} = cachedData;
   434→
   435→      return {
   436→        blockInput: {
   437→          block: null,
   438→          blockRootHex: blockHex,
   439→          cachedData,
   440→          blockInputPromise,
   441→        },
   442→        blockInputMeta: {pending: GossipedInputType.block, haveBlobs: blobsCache.size, expectedBlobs: null},
   443→      };
   444→    }
   445→
   446→    if (fork === ForkName.fulu) {
   447→      const {dataColumnsCache} = cachedData as CachedDataColumns;
   448→
   449→      return {
   450→        blockInput: {
   451→          block: null,
   452→          blockRootHex: blockHex,
   453→          cachedData,
   454→          blockInputPromise,
   455→        },
   456→        blockInputMeta: {pending: GossipedInputType.block, haveColumns: dataColumnsCache.size, expectedColumns: null},
   457→      };
   458→    }
   459→
   460→    throw Error(`invalid fork=${fork} data not implemented`);
   461→
   462→    /**
   463→     * TODO: @matthewkeil this code was unreachable.  Commented to remove lint error but need to verify the condition
   464→     * again to make sure this is not necessary before deleting it
   465→     *
   466→     * DO NOT DELETE until verified can be removed
   467→     */
   468→    // will need to wait for the block to showup
   469→    // if (cachedData === undefined) {
   470→    //   throw Error("Missing cachedData for deneb+ blobs");
   471→    // }
   472→    // const {blobsCache} = cachedData as CachedBlobs;
   473→
   474→    // return {
   475→    //   blockInput: {
   476→    //     block: null,
   477→    //     blockRootHex: blockHex,
   478→    //     cachedData: cachedData as CachedData,
   479→    //     blockInputPromise,
   480→    //   },
   481→    //   blockInputMeta: {pending: GossipedInputType.block, haveBlobs: blobsCache.size, expectedBlobs: null},
   482→    // };
   483→  }
   484→}
   485→
   486→export function getEmptyBlockInputCacheEntry(fork: ForkName, globalCacheId: number): BlockInputCacheType {
   487→  // Capture both the promise and its callbacks for blockInput and final availability
   488→  // It is not spec'ed but in tests in Firefox and NodeJS the promise constructor is run immediately
   489→  let resolveBlockInput: ((block: BlockInput) => void) | null = null;
