   498→  }
   499→
   500→  if (fork === ForkName.deneb || fork === ForkName.electra) {
   501→    let resolveAvailability: ((blobs: BlockInputBlobs) => void) | null = null;
   502→    const availabilityPromise = new Promise<BlockInputBlobs>((resolveCB) => {
   503→      resolveAvailability = resolveCB;
   504→    });
   505→
   506→    if (resolveAvailability === null) {
   507→      throw Error("Promise Constructor was not executed immediately");
   508→    }
   509→
   510→    const blobsCache = new Map();
   511→    const cachedData: CachedData = {
   512→      fork,
   513→      blobsCache,
   514→      availabilityPromise,
   515→      resolveAvailability,
   516→      cacheId: ++globalCacheId,
   517→    };
   518→    return {fork, blockInputPromise, resolveBlockInput, cachedData};
   519→  }
   520→
   521→  if (fork === ForkName.fulu) {
   522→    let resolveAvailability: ((blobs: BlockInputDataColumns) => void) | null = null;
   523→    const availabilityPromise = new Promise<BlockInputDataColumns>((resolveCB) => {
   524→      resolveAvailability = resolveCB;
   525→    });
   526→
   527→    if (resolveAvailability === null) {
   528→      throw Error("Promise Constructor was not executed immediately");
   529→    }
   530→
   531→    const dataColumnsCache = new Map();
   532→    const cachedData: CachedData = {
   533→      fork,
   534→      dataColumnsCache,
   535→      availabilityPromise,
   536→      resolveAvailability,
   537→      cacheId: ++globalCacheId,
   538→      calledRecover: false,
   539→    };
   540→    return {fork, blockInputPromise, resolveBlockInput, cachedData};
   541→  }
   542→
   543→  throw Error(`Invalid fork=${fork} for getEmptyBlockInputCacheEntry`);
